-- The app's starter Legal Updates, published as the app showed them before
-- news came from the server. Staff can correct or retire them in the portal.
INSERT INTO "news_articles" ("id", "external_ref", "status", "category", "title", "summary", "key_points", "why_it_matters", "source", "event_date", "read_minutes", "published_at") VALUES
  (gen_random_uuid(), 'tn-governor-assent', 'published', 'supreme_court', 'Supreme Court sets timelines for Governors on State Bills',
   'In State of Tamil Nadu v. Governor of Tamil Nadu, the Supreme Court held that a Governor cannot sit indefinitely on Bills passed by a State legislature and laid down time limits for acting under Article 200.',
   ARRAY['A Governor must act on a Bill within a reasonable time — there is no "pocket veto".', 'The Court indicated outer time limits for assent, withholding or reserving a Bill.', 'Inaction beyond those limits can be challenged before constitutional courts.']::text[],
   'It strengthens federalism by ensuring elected State legislatures are not stalled by delays at Raj Bhavan.',
   'Supreme Court of India, 8 April 2025', '2025-04-08', 3, now()),
  (gen_random_uuid(), 'waqf-amendment-2025', 'published', 'legislation', 'Waqf (Amendment) Act, 2025 receives Presidential assent',
   'Parliament amended the Waqf Act, 1995, changing how waqf properties are registered, managed and adjudicated. The law received assent in April 2025 and its validity has been challenged before the Supreme Court.',
   ARRAY['Renames the law as the Unified Waqf Management, Empowerment, Efficiency and Development Act.', 'Changes the composition of the Central Waqf Council and State Waqf Boards.', 'Petitions challenging the amendments were taken up by the Supreme Court.']::text[],
   'Waqf boards manage significant land holdings; the changes affect property rights, administration and minority-rights debates.',
   'Gazette of India, April 2025', '2025-04-05', 3, now()),
  (gen_random_uuid(), 'pocso-csam', 'published', 'supreme_court', 'Storing or watching child sexual abuse material is an offence',
   'In Just Rights for Children Alliance v. S. Harish, the Supreme Court held that viewing, possessing or storing child sexual exploitative material can be an offence under the POCSO Act and the IT Act, overturning a Madras High Court ruling.',
   ARRAY['Mere possession with intent to share, or failure to delete/report, attracts POCSO Section 15.', 'The Court urged Parliament to use the term "child sexual exploitative and abuse material".', 'Courts should not use the phrase "child pornography".']::text[],
   'It closes a gap that treated private viewing as harmless and strengthens child protection online.',
   'Supreme Court of India, 23 September 2024', '2024-09-23', 3, now()),
  (gen_random_uuid(), 'sc-subclassification', 'published', 'supreme_court', 'States may sub-classify Scheduled Castes for reservation',
   'A seven-judge Constitution Bench in State of Punjab v. Davinder Singh held (6:1) that States can sub-classify Scheduled Castes to give more benefits to the most backward groups, overruling E.V. Chinnaiah (2004).',
   ARRAY['Sub-classification must be backed by empirical data on backwardness and representation.', 'A State cannot reserve 100% of the SC quota for one sub-group.', 'Several judges suggested a "creamy layer" test for SCs and STs.']::text[],
   'It reshapes how reservation benefits are distributed within Scheduled Castes across States.',
   'Supreme Court of India, 1 August 2024', '2024-08-01', 4, now()),
  (gen_random_uuid(), 'explainer-zero-fir', 'published', 'explainer', 'Explainer: Zero FIR and e-FIR under BNSS',
   'You can report a cognizable offence at any police station, regardless of where it happened. The station must register a "Zero FIR" and transfer it to the station with jurisdiction.',
   ARRAY['Recognised in BNSS Section 173(1).', 'Information can be given electronically; it must be signed within three days to be taken on record.', 'You are entitled to a free copy of the FIR.']::text[],
   'Victims — especially of crimes against women — no longer get turned away over jurisdiction.',
   'Bharatiya Nagarik Suraksha Sanhita, 2023', '2024-07-02', 2, now()),
  (gen_random_uuid(), 'new-criminal-laws', 'published', 'legislation', 'BNS, BNSS and BSA replace IPC, CrPC and Evidence Act',
   'From 1 July 2024, the Bharatiya Nyaya Sanhita, Bharatiya Nagarik Suraksha Sanhita and Bharatiya Sakshya Adhiniyam replaced the colonial-era IPC, CrPC and Indian Evidence Act for offences committed on or after that date.',
   ARRAY['Zero FIR and e-FIR are now expressly recognised (BNSS Section 173).', 'Community service is introduced as a punishment for certain petty offences.', 'Electronic records are treated as primary evidence in many cases (BSA).']::text[],
   'Every citizen, police officer and lawyer now works with new section numbers — older cases still run under the old codes.',
   'Ministry of Home Affairs notification', '2024-07-01', 4, now()),
  (gen_random_uuid(), 'explainer-legal-aid', 'published', 'explainer', 'Explainer: Who can get free legal aid?',
   'Under Section 12 of the Legal Services Authorities Act, 1987, women, children, SC/ST members, persons in custody, persons with disabilities, victims of disasters and people below the income limit are entitled to free legal services.',
   ARRAY['Apply at the District/Taluk Legal Services Authority or online via NALSA.', 'Call the national legal aid helpline 15100.', 'Free legal aid flows from Article 39A of the Constitution.']::text[],
   'Lack of money should never stop anyone from getting justice.',
   'Legal Services Authorities Act, 1987', '2024-06-15', 2, now()),
  (gen_random_uuid(), 'electoral-bonds', 'published', 'supreme_court', 'Electoral Bonds Scheme struck down as unconstitutional',
   'In Association for Democratic Reforms v. Union of India, a five-judge bench unanimously held the Electoral Bonds Scheme violated voters'' right to information under Article 19(1)(a).',
   ARRAY['Anonymous political funding was held to violate the right to information.', 'SBI was directed to stop issuing bonds and disclose details to the Election Commission.', 'Related amendments to the Companies Act and RP Act were struck down.']::text[],
   'It strengthens transparency in political funding and voters'' informed choice.',
   'Supreme Court of India, 15 February 2024', '2024-02-15', 3, now()),
  (gen_random_uuid(), 'mediation-act', 'published', 'legislation', 'Mediation Act, 2023 makes pre-litigation mediation mainstream',
   'The Mediation Act, 2023 creates a framework for institutional, online and community mediation, with mediated settlement agreements enforceable like court decrees.',
   ARRAY['Mediation should ordinarily conclude within 120 days, extendable by 60 days.', 'Establishes the Mediation Council of India.', 'Online mediation is expressly recognised.']::text[],
   'Faster, cheaper resolution of disputes and less burden on courts.',
   'Act No. 32 of 2023', '2023-09-14', 3, now()),
  (gen_random_uuid(), 'dpdp-act', 'published', 'legislation', 'Digital Personal Data Protection Act, 2023 — what it means for you',
   'India''s first comprehensive data protection law gives individuals ("Data Principals") rights over their personal data and places duties on companies ("Data Fiduciaries"). It is being operationalised in phases through Rules.',
   ARRAY['Consent must be free, specific, informed and withdrawable.', 'You can seek access, correction and erasure of your personal data.', 'A Data Protection Board adjudicates breaches; penalties can reach ₹250 crore.']::text[],
   'Apps and companies must now justify why they collect your data and protect it.',
   'Act No. 22 of 2023', '2023-08-11', 4, now())
ON CONFLICT ("external_ref") DO NOTHING;
